import type { SupabaseClient } from '@supabase/supabase-js'
import { withFreshInvoiceNumber } from '@/lib/invoiceNumber'
import { invoicePartySnapshots, updateInvoiceRow } from '@/lib/invoicePersist'
import { calendarDateInBucharest } from '@/lib/dates'
import { remainingOf, withConvertedInvoiceAmounts, type InvoiceMoneyRow } from '@/lib/invoiceMath'

/**
 * One-click issue of a draft (typically one generated by a recurring series): allocates the
 * number now and freezes the seller/buyer snapshots, exactly like "Emite" in the editor.
 */
export async function issueDraft(client: SupabaseClient, opts: {
  invoice: { id: string; series?: string | null; client_id?: string | null; user_id: string }
  company?: (Record<string, unknown> & { id?: string; invoice_series?: string | null; invoice_start_number?: number | null }) | null
  ownerUserId: string
}) {
  const { invoice, company } = opts
  const { data: buyer } = invoice.client_id
    ? await client.from('clients').select('*').eq('id', invoice.client_id).maybeSingle()
    : { data: null }
  const series = company?.invoice_series || invoice.series || 'FCT'
  const result = await withFreshInvoiceNumber(client, {
    series,
    companyId: company?.id,
    userId: opts.ownerUserId || invoice.user_id,
    startNumber: company?.invoice_start_number
  }, invoice_number => updateInvoiceRow(client, invoice.id, {
    status: 'sent',
    series,
    invoice_number,
    ...invoicePartySnapshots({
      status: 'sent',
      seller: company as Record<string, unknown> | null,
      buyer: buyer as Record<string, unknown> | null
    })
  }))
  if (result.error) throw new Error(result.error.message || 'Factura nu a putut fi emisă.')
  return `${series}${result.invoiceNumber}`
}

/** Issued invoices of a recurring series still unpaid after their due date. */
export async function overdueInSeries(client: SupabaseClient, recurringId: string, today = calendarDateInBucharest(0)) {
  const { data } = await client
    .from('invoices')
    .select('id, status, total, subtotal, tva_amount, amount_paid, prepaid_amount, exchange_rate, due_date, invoice_items(quantity, unit_price, tva_rate, total)')
    .eq('recurring_invoice_id', recurringId)
    .in('status', ['sent', 'overdue', 'spv'])
    .lt('due_date', today)
  let count = 0
  let amount = 0
  for (const row of (data || []) as unknown as InvoiceMoneyRow[]) {
    const left = remainingOf(withConvertedInvoiceAmounts(row))
    if (left > 0.01) { count++; amount += left }
  }
  return { count, amount: Math.round(amount * 100) / 100 }
}
